import {EVENTS,RULE_ISSUES,categories,makeDraw,resolveDraw,saveWinner,clearWinner,signature,clubConflicts,fingerprintCounts,initialState,validateAthlete,classify} from './engine.js';
import {icon} from './icons.js';
import * as Client from './client.js';
import {ROLES,STATUSES,ageAt,managesTournament,managesProfile,canEnter} from './workspace.js';
const isDemo=Client.isDemo;
const plural=(n,one,few,many)=>n===1?one:n%10>=2&&n%10<=4&&(n%100<12||n%100>14)?few:many;
let workspace=null,state={tournament:{},athletes:[],draws:{},activity:[]},saving=false;
let activeId=sessionStorage.getItem('matdraw.activeTournament');
const ui={page:'tournaments',category:null,search:'',event:'all',filter:'all',rosterSearch:'',rosterFilter:'all',round:0,menu:false,screenPart:0,screenAuto:false,databaseSearch:'',tournamentSearch:'',showArchive:false};
let previousFocus=null;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const athlete=id=>state.athletes.find(a=>a.id===id);
const short=n=>n.split(' ').map((p,i)=>i===0?p:p).join(' ');
const initials=n=>esc(n.trim().split(/\s+/).slice(0,2).map(p=>p[0]).join(''));
const button=(label,action,cls='secondary',extra='')=>`<button class="btn ${cls}" data-action="${action}" ${extra}>${label}</button>`;
const badge=(text,type='neutral')=>`<span class="badge ${type}">${text}</span>`;
const logo=`<span class="brand-mark">${icon('bracket')}</span><span class="wordmark">MatDraw<span class="brand-dot">.</span></span>`;
const footer=()=>`<footer class="footer"><span>MatDraw <span class="footer-dot">·</span> Turniej pod kontrolą.</span><a class="creator" href="https://mdcse.com" target="_blank" rel="noopener noreferrer" aria-label="Wykonano przez MEDUCASE — przejdź do mdcse.com"><span>Wykonano przez</span><img src="./assets/meducase.png" alt="MEDUCASE" width="150" height="48"></a></footer>`;
function allCats(){return categories(state.athletes);}
function selected(){const items=allCats().items;return items.find(c=>c.id===ui.category)||items[0];}
function ensureDraw(c){return c?state.draws[c.id]||null:null;}
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),4800);}
function stats(){const s=fingerprintCounts(state.athletes);return `<div class="stats"><div class="stat"><span class="stat-icon">${icon('users')}</span><div><strong>${s.active}</strong><span>Zawodników</span></div><small>${s.clubs} klubów</small></div><div class="stat"><span class="stat-icon">${icon('bracket')}</span><div><strong>${s.categories}</strong><span>Kategorii</span></div><small>${s.categories-s.alerts} z min. 3 osobami</small></div><div class="stat"><span class="stat-icon">${icon('clipboard')}</span><div><strong>${state.athletes.filter(a=>a.presence==='present').length}<em>/${s.athletes}</em></strong><span>Po kontroli</span></div><small>Waga i obecność</small></div><button class="stat stat-alert" data-action="attention"><span class="stat-icon">${icon('alert')}</span><div><strong>${s.alerts+s.unassigned}</strong><span>Wymagają uwagi</span></div><small>Sprawdź ${icon('arrow')}</small></button></div>`;}
function shell(content,title,subtitle,actions=''){
 const user=workspace.user,t=state.tournament,s=fingerprintCounts(state.athletes),club=workspace.clubs.find(c=>c.id===user.clubId);
 const globalNav=[['tournaments','trophy','Turnieje'],['database','users','Baza zawodników'],...(user.role==='admin'?[['accounts','shield','Konta i role']]:[])];
 const eventNav=t.id?[...(user.role!=='club'?[['overview','grid','Przegląd turnieju']]:[]),['athletes','users',user.role==='club'?'Zgłoszenia klubu':'Zgłoszenia'],...(user.role!=='club'?[['checkin','clipboard','Kontrola startowa'],['draws','bracket','Drabinki']]:[])]:[];
 const nav=items=>items.map(([page,i,name])=>`<button class="nav-link ${ui.page===page?'active':''}" data-page="${page}" ${ui.page===page?'aria-current="page"':''}>${icon(i)}<span>${name}</span>${page==='athletes'?'<span class="nav-count">'+s.athletes+'</span>':''}</button>`).join('');
 return `<div class="app-shell"><aside class="sidebar ${ui.menu?'open':''}" aria-label="Nawigacja główna"><a href="#tournaments" class="brand" data-page="tournaments" aria-label="MatDraw — turnieje">${logo}</a><nav>${nav(globalNav)}</nav><div class="nav-divider"></div><label class="sidebar-label" for="active-tournament">AKTYWNY TURNIEJ</label><select id="active-tournament" class="tournament-switch" data-control="tournament">${workspace.tournaments.map(x=>`<option value="${x.id}" ${t.id===x.id?'selected':''}>${esc(x.name)}</option>`).join('')||'<option>Brak turniejów</option>'}</select><nav>${nav(eventNav)}${t.id&&user.role!=='club'?`<button class="nav-link" data-action="project">${icon('screen')}<span>Ekran hali</span>${icon('external','nav-end')}</button>`:''}</nav><div class="sidebar-bottom"><div class="demo-note"><span class="pulse-dot"></span><strong>${isDemo?'Podgląd demonstracyjny':'Połączono z serwerem'}</strong><p>${isDemo?'Dane i konta testowe w tej przeglądarce.':'Wspólna baza zawodników i turniejów.'}</p></div><button class="nav-link" data-page="rules">${icon('settings')}<span>Zasady turnieju</span></button><button class="nav-link" data-page="architecture">${icon('info')}<span>O projekcie</span></button><div class="profile"><span class="avatar organizer">${initials(club?.name||'Klub')}</span><div><strong>${esc(ROLES[user.role])}</strong><span>${esc(club?.name||'')}</span></div></div><button class="nav-link compact-nav" data-action="my-account">${icon('settings')}<span>Moje konto</span></button><button class="nav-link compact-nav" data-action="logout">${icon('left')}<span>Wyloguj się</span></button></div></aside>${ui.menu?'<button class="nav-backdrop" data-action="menu" aria-label="Zamknij menu"></button>':''}<div class="main-shell"><header class="topbar"><div class="topbar-left"><button class="icon-btn mobile-only" data-action="menu" aria-label="Otwórz menu">${icon('menu')}</button><span class="breadcrumb">${['tournaments','database','accounts'].includes(ui.page)?'MatDraw':esc(t.name||'MatDraw')}</span>${icon('right','crumb-arrow')}<span class="breadcrumb current">${title}</span></div><div class="topbar-right">${isDemo?'<span class="demo-badge">DEMO</span>':''}<button class="text-btn" data-action="refresh" aria-label="Odśwież dane">${icon('refresh')}<span>${saving?'Zapisywanie…':isDemo?'Zapis lokalny':'Dane z serwera'}</span></button><span class="avatar organizer small" title="${esc(ROLES[user.role])}">${initials(club?.name||'Klub')}</span></div></header><main id="main" class="main"><div class="page-heading"><div><div class="eyebrow">${['tournaments','database','accounts'].includes(ui.page)?'PRZESTRZEŃ MATDRAW':'CENTRUM TURNIEJU'}</div><h1>${title}</h1><p>${subtitle}</p></div><div class="heading-actions">${actions}</div></div>${content}</main>${footer()}</div></div>`;
}
function roundName(index,total){const remaining=total-index;return remaining===1?'Finał':remaining===2?'Półfinały':remaining===3?'Ćwierćfinały':remaining===4?'1/8 finału':remaining===5?'1/16 finału':'1/32 finału';}
function matchHtml(m,{interactive=true,compact=false}={}){
 const a=athlete(m.a),b=athlete(m.b);
 if(m.auto&&!a&&!b)return '<div class="empty-match" aria-label="Pusta gałąź"></div>';
 const title=m.recorded?'Zakończona':m.auto?'Wolny los':m.ready?'Do rozegrania':'Oczekiwanie';
 const row=(p,id,settled,side)=>`<div class="fighter ${side} ${m.winner===id&&id?'winner':''} ${!p?'placeholder':''}"><span class="fighter-bar"></span><span class="fighter-text"><strong>${p?esc(p.name):settled?'Wolny los':'Zwycięzca poprzedniej walki'}</strong>${p?'<small>'+esc(p.club)+(p.champion?' <span class="champion-star" title="Mistrz Polski / Europy">★</span>':'')+'</small>':''}</span>${m.winner===id&&id?icon('check','win-check'):''}</div>`;
 const active=interactive&&managesTournament(workspace.user,state.tournament)&&state.tournament.status!=='finished'&&!m.auto&&(m.ready||m.recorded);
 const tag=active?'button':'div';
 return `<${tag} class="match ${m.auto?'bye':''} ${m.recorded?'complete':''} ${m.ready?'ready':''} ${compact?'compact':''}" ${active?`data-action="match" data-match="${m.id}" aria-label="Walka ${m.number}: ${esc(a?.name)} i ${esc(b?.name)}. ${title}"`:''}><div class="match-label"><span>${m.auto?'AWANS':'WALKA '+String(m.number).padStart(2,'0')}</span><span>${m.recorded?icon('check'):m.ready?'<i class="tiny-dot"></i>':''}${title}</span></div>${row(a,m.a,m.aSettled,'blue')}${row(b,m.b,m.bSettled,'red')}</${tag}>`;
}
function bracketHtml(draw,interactive=true,opts={}){
 const rounds=opts.roundSet||resolveDraw(draw),n=rounds.length,fullTotal=opts.totalRounds||n,startRound=opts.startRound||0;
 const round=Math.min(ui.round,n-1);
 return `<div class="mobile-round-control"><label for="round-select">Runda</label><select id="round-select" data-control="round">${rounds.map((r,i)=>`<option value="${i}" ${i===round?'selected':''}>${roundName(i+startRound,fullTotal)}</option>`).join('')}</select></div><div class="bracket-scroll ${opts.screen?'screen-bracket':''}"><div class="bracket-tree" style="--rounds:${n};--slots:${rounds[0].length}">${rounds.map((matches,i)=>`<section class="round ${i===round?'mobile-active':''}" aria-label="${roundName(i+startRound,fullTotal)}"><div class="round-title"><span>${roundName(i+startRound,fullTotal)}</span><small>${i===n-1?icon('trophy'):String(i+1).padStart(2,'0')}</small></div><div class="round-matches">${matches.map(m=>`<div class="match-position ${m.auto&&!m.winner?'empty-position':''}">${matchHtml(m,{interactive})}</div>`).join('')}</div></section>`).join('')}</div></div>`;
}
function categoryCard(c){const d=state.draws[c.id],done=d&&resolveDraw(d).at(-1)[0].winner;return `<button class="category-card ${selected()?.id===c.id?'selected':''}" data-action="category" data-id="${esc(c.id)}"><span class="cat-card-top"><span>${c.code}</span>${c.underfilled?badge(c.athletes.length+' os.','warning'):done?badge('Zakończona','success'):'<span class="category-number">'+c.athletes.length+' os.</span>'}</span><strong>${esc(c.title)}</strong><span class="cat-sub">${esc(c.ageLabel)} · ${c.sexLabel}</span><span class="cat-band">${esc(c.band)}${c.gradeType==='cup'&&c.event!=='forms'?' · Cup':''}${c.gradeType==='dan'&&c.event!=='forms'?' · Dan':''}</span></button>`;}
function listView(c,print=false){return `<div class="list-description">${icon('clipboard')}<div><strong>Lista startowa</strong><p>Wzór roboczy. Punktacja i kolejność prób wymagają regulaminu od trenera.</p></div></div><div class="table-wrap"><table class="roster-table start-list"><thead><tr><th>Nr</th><th>Zawodnik</th><th>Klub</th><th>Próba 1</th><th>Próba 2</th><th>Wynik</th></tr></thead><tbody>${c.athletes.map((a,i)=>`<tr><td>${i+1+(c.printOffset||0)}</td><td><strong>${esc(a.name)}</strong></td><td>${esc(a.club)}</td><td>—</td><td>—</td><td>—</td></tr>`).join('')}</tbody></table></div>`;}
function drawsPage(){
 const {items,unassigned}=allCats();let c=selected();if(!c)return shell('<div class="empty-state">Brak zgłoszeń. Dodaj pierwszego zawodnika.</div>','Kategorie i drabinki','Zgłoszenia automatycznie tworzą kategorie.',button(icon('plus')+' Dodaj zawodnika','add','primary'));
 ui.category=c.id;
 const query=ui.search.toLocaleLowerCase('pl');
 const filtered=items.filter(x=>(ui.event==='all'||x.event===ui.event)&&(ui.filter!=='attention'||x.underfilled)&&[x.title,x.subtitle,x.code].join(' ').toLocaleLowerCase('pl').includes(query));
 if(filtered.length&&!filtered.some(x=>x.id===c.id)){c=filtered[0];ui.category=c.id;ui.round=0;}
 const d=ensureDraw(c),rounds=d?resolveDraw(d):null,final=rounds?.at(-1)[0],conflicts=d?clubConflicts(d,c.athletes):0;
 const warning=unassigned.length+items.filter(x=>x.underfilled).length;
 let content=`${stats()}${warning?`<div class="notice"><span class="notice-icon">${icon('alert')}</span><p><strong>Sprawdź zgłoszenia przed losowaniem.</strong> ${items.filter(x=>x.underfilled).length} kategorie mają mniej niż 3 osoby${unassigned.length?' · '+unassigned.length+' start wymaga przypisania':''}.</p><button data-action="attention">Zobacz szczegóły ${icon('arrow')}</button></div>`:''}<div class="workspace-toolbar"><div class="segmented" role="group" aria-label="Filtr kategorii"><button class="${ui.filter==='all'?'active':''}" data-filter="all">Wszystkie <span>${items.length}</span></button><button class="${ui.filter==='attention'?'active':''}" data-filter="attention">Wymagają uwagi <span>${items.filter(x=>x.underfilled).length}</span></button></div><label class="event-filter"><span class="sr-only">Konkurencja</span><select data-control="event"><option value="all">Wszystkie konkurencje</option>${Object.entries(EVENTS).map(([k,v])=>`<option value="${k}" ${ui.event===k?'selected':''}>${v}</option>`).join('')}</select></label></div><div class="draw-workspace"><aside class="category-panel" aria-label="Kategorie"><div class="category-search">${icon('search')}<input type="search" id="category-search" placeholder="Szukaj kategorii…" aria-label="Szukaj kategorii" value="${esc(ui.search)}"></div><div class="category-list">${filtered.map(categoryCard).join('')||'<div class="empty-state small-empty">Brak pasujących kategorii.</div>'}</div></aside><section class="draw-panel"><div class="mobile-category"><label for="category-select">Wybierz kategorię</label><select id="category-select" data-control="category">${filtered.map(x=>`<option value="${esc(x.id)}" ${x.id===c.id?'selected':''}>${x.code} · ${esc(x.title)} · ${esc(x.subtitle)} (${x.athletes.length})</option>`).join('')}</select></div><div class="draw-header"><div><div class="draw-eyebrow"><span class="category-code">${c.code}</span>${badge(c.underfilled?'Wymaga decyzji':final?.winner?'Zakończona':d&&Object.keys(d.results).length?'W toku':c.type==='list'?'Lista startowa':'Gotowa do rozegrania',c.underfilled?'warning':final?.winner?'success':'teal')}</div><h2>${esc(c.title)}</h2><p>${esc(c.subtitle)}${c.event!=='forms'&&c.gradeType!=='all'?' · '+(c.gradeType==='dan'?'Dan':'Cup'):''}</p></div><div class="draw-meta"><span>${icon('users')} ${c.athletes.length} zawodników</span><span>${icon('shield')} ${new Set(c.athletes.map(a=>a.club)).size} klubów</span></div></div><div class="draw-subbar"><span>${icon(c.type==='list'?'clipboard':'bracket')} ${c.type==='list'?'Konkurencja punktowa':d?'System pucharowy · '+d.size+' miejsc':'Minimum 3 zawodników'}</span>${d&&managesTournament(workspace.user,state.tournament)&&state.tournament.status!=='finished'?`<button data-action="redraw" class="text-btn" ${Object.keys(d.results).length?'disabled title="Zapisano wyniki — losowanie zablokowane"':''}>${icon('refresh')} Losuj ponownie</button>`:''}</div>${c.underfilled?`<div class="empty-state underfilled"><div class="empty-illustration">${icon('users')}</div><h3>${c.athletes.length===1?'Jeden zawodnik to jeszcze nie turniej.':'Ta kategoria potrzebuje trzeciej osoby.'}</h3><p>Wymagane są co najmniej 3 osoby. Organizator powinien zdecydować o kategorii przed losowaniem.</p><div class="waiting-athletes">${c.athletes.map(a=>`<div><span class="avatar">${initials(a.name)}</span><span><strong>${esc(a.name)}</strong><small>${esc(a.club)}</small></span></div>`).join('')}</div>${button('Przejdź do zgłoszeń','roster','secondary')}</div>`:c.type==='list'?listView(c):d?bracketHtml(d):`<div class="empty-state"><div class="empty-illustration">${icon('bracket')}</div><h3>${c.athletes.length>64?'Kategoria wymaga podziału':'Zgłoszenia są gotowe do losowania.'}</h3><p>${c.athletes.length>64?'Maksymalnie 64 osoby w drabince.':'Zapisz rozstawienie, aby rozpocząć walki.'}</p>${c.athletes.length<=64&&managesTournament(workspace.user,state.tournament)&&state.tournament.status!=='finished'?button('Losuj drabinkę','create-draw','primary'):''}</div>`}${d?`<div class="draw-footnote"><span class="${conflicts?'warning-text':''}">${icon(conflicts?'alert':'shield')}${conflicts?conflicts+' pary z tego samego klubu — sprawdź losowanie':'Rozdzielono kluby w pierwszych pewnych parach'}</span><span>${icon('info')} Kliknij walkę, aby wpisać zwycięzcę</span></div>${final?.winner?`<div class="winner-banner">${icon('trophy')}<div><small>ZWYCIĘZCA KATEGORII</small><strong>${esc(athlete(final.winner)?.name)}</strong></div>${badge('Finał zakończony','success')}<p>Brąz: zasada do ustalenia.</p></div>`:''}`:''}</section></div>`;
 if(!filtered.length)content=content.replace(/<section class="draw-panel">[\s\S]*<\/section><\/div>$/, '<section class="draw-panel empty-state"><h3>Brak pasujących kategorii</h3><p>Zmień filtr konkurencji lub wyszukiwaną frazę.</p></section></div>');
 return shell(content,'Kategorie i drabinki','Od pierwszego losowania do ostatniej walki.',button(icon('print')+' Drukuj','print')+button(icon('screen')+' Ekran hali','project','primary'));
}
function overviewPage(){const {items,unassigned}=allCats();const completed=Object.values(state.draws).filter(d=>resolveDraw(d).at(-1)[0].winner).length;return shell(`${stats()}<div class="overview-grid"><section class="panel overview-main"><div class="panel-heading"><div><div class="eyebrow">NA DOBRY POCZĄTEK</div><h2>Wszystko na swoim miejscu.</h2><p>Trzy kroki od zgłoszeń do gotowego turnieju.</p></div>${icon('bracket')}</div><div class="workflow-step"><span>01</span><div><h3>Zbierz zgłoszenia</h3><p>Klub dodaje zawodników oraz ich konkurencje. Kategorie uzupełniają się automatycznie.</p></div><button data-page="athletes" class="icon-btn" aria-label="Zobacz zawodników">${icon('arrow')}</button></div><div class="workflow-step"><span>02</span><div><h3>Sprawdź wagę i obecność</h3><p>Jedna korekta aktualizuje wszystkie starty zawodnika.</p></div><button data-page="checkin" class="icon-btn" aria-label="Przejdź do kontroli">${icon('arrow')}</button></div><div class="workflow-step"><span>03</span><div><h3>Rozegraj turniej</h3><p>Zapisuj zwycięzców. Drabinki są gotowe do druku i wyświetlenia.</p></div><button data-page="draws" class="icon-btn" aria-label="Przejdź do drabinek">${icon('arrow')}</button></div></section><section class="panel attention-card"><div class="panel-heading"><h2>Do sprawdzenia</h2>${icon('alert')}</div>${items.filter(c=>c.underfilled).map(c=>`<button class="attention-row" data-action="category" data-id="${esc(c.id)}"><span class="attention-count">${c.athletes.length}</span><div><strong>${esc(c.title)}</strong><small>${esc(c.subtitle)}</small></div>${icon('right')}</button>`).join('')}${unassigned.map(x=>`<div class="attention-row"><span class="attention-count">!</span><div><strong>${esc(x.athlete.name)}</strong><small>${esc(x.reason)}</small></div></div>`).join('')}<p class="muted small">Kategorie z mniej niż 3 osobami pozostają bez losowania.</p></section></div><section class="panel activity"><div class="panel-heading"><h2>Ostatnie zmiany</h2><span>${completed} kategorii zakończonych</span></div>${state.activity.length?state.activity.slice(0,6).map(x=>`<div class="activity-row">${icon('check')}<span>${esc(x.text)}</span><time>${new Date(x.time).toLocaleTimeString('pl-PL',{hour:'2-digit',minute:'2-digit',timeZone:'Europe/Warsaw'})}</time></div>`).join(''):'<div class="empty-activity">'+icon('clock')+' Tutaj pojawią się zapisane wyniki, zgłoszenia i korekty.</div>'}</section>`,'Przegląd turnieju',esc(state.tournament.name)+' · '+formatDate(state.tournament.date)+' · '+esc(state.tournament.city),button(icon('plus')+' Dodaj zawodnika','add','primary'));}
function rosterPage(checkin=false){const user=workspace.user,t=state.tournament,q=ui.rosterSearch.toLocaleLowerCase('pl');const list=state.athletes.filter(a=>(a.name+' '+a.club).toLocaleLowerCase('pl').includes(q)&&(ui.rosterFilter==='all'||a.presence===ui.rosterFilter));return shell(`<div class="notice info-notice">${icon(checkin?'scale':'users')}<p>${checkin?'<strong>Kontrola wyłącznie tego turnieju.</strong> Waga i nieobecność aktualizują starty tutaj.':'<strong>'+esc(t.name)+'</strong> Zgłoszenia są kopiami danych z kartoteki. '+STATUSES[t.status]+'.'}</p></div><section class="panel roster-panel"><div class="roster-toolbar"><div class="search-field">${icon('search')}<input id="roster-search" type="search" placeholder="Szukaj zawodnika lub klubu…" aria-label="Szukaj zawodnika lub klubu" value="${esc(ui.rosterSearch)}"></div><select data-control="roster-filter" aria-label="Status kontroli">${[['all','Wszystkie statusy'],['pending','Oczekują na kontrolę'],['present','Obecni'],['absent','Nieobecni']].map(([v,l])=>`<option value="${v}" ${ui.rosterFilter===v?'selected':''}>${l}</option>`).join('')}</select><span class="muted small">${list.length} osób</span></div><div class="table-wrap"><table class="roster-table"><thead><tr><th>Zawodnik</th><th>Klub</th><th>${checkin?'Zgłoszona → kontrolna':'Wiek / stopień'}</th><th>${checkin?'Status':'Konkurencje'}</th><th>Działania</th></tr></thead><tbody>${list.map(a=>`<tr class="${a.presence==='absent'?'absent':''}"><td data-label="Zawodnik"><div class="athlete-cell"><span class="avatar">${initials(a.name)}</span><span><strong>${esc(a.name)}</strong><small>${a.height} cm${a.champion?' · Mistrz PL / EU':''}</small></span></div></td><td data-label="Klub">${esc(a.club)}</td><td data-label="${checkin?'Waga':'Wiek / stopień'}">${checkin?`${a.weight.toFixed(1)} → <strong>${a.actualWeight!=null?a.actualWeight.toFixed(1):'—'}</strong> kg`:`${a.age} lat · ${a.grade} ${a.gradeType==='dan'?'Dan':'Cup'}`}</td><td data-label="${checkin?'Status':'Konkurencje'}">${checkin?badge(a.presence==='present'?'Po kontroli':a.presence==='absent'?'Nieobecny':'Do kontroli',a.presence==='present'?'success':a.presence==='absent'?'neutral':'warning'):`<span class="event-tags">${a.events.map(e=>`<span>${EVENTS[e]}</span>`).join('')}</span>`}</td><td class="row-action"><div class="row-buttons">${checkin?(managesTournament(user,t)&&t.status!=='finished'?button('Sprawdź','check-athlete','small-btn',`data-id="${a.id}"`):'<span class="muted small">Podgląd</span>'):canEditEntry(a)?button('Edytuj','edit-entry','small-btn',`data-id="${a.profileId}"`)+button('Wycofaj','remove-entry','small-btn danger-text',`data-id="${a.id}"`):'<span class="muted small">Podgląd</span>'}</div></td></tr>`).join('')||'<tr><td colspan="5" class="empty-state"><h3>Brak zgłoszeń w tym turnieju.</h3><p>Dodaj zawodników z bazy albo utwórz nowe kartoteki.</p></td></tr>'}</tbody></table></div></section>`,checkin?'Kontrola startowa':user.role==='club'?'Zgłoszenia klubu':'Zgłoszenia do turnieju',esc(t.name)+' · '+formatDate(t.date),!checkin&&canEnter(user,t)?button(icon('plus')+' Nowy zawodnik','new-entry')+button(icon('users')+' Dodaj z bazy','entry-picker','primary'):'');}
function rulesPage(){return shell(`<div class="notice info-notice">${icon('info')}<p>Reguły na podstawie dokumentu trenera Bogusława. Poniższe niejasności pozostają otwarte — prototyp nie nadaje im statusu zatwierdzonego regulaminu.</p></div><div class="rules-grid">${RULE_ISSUES.map((r,i)=>`<section class="panel rule-card"><div class="rule-number">${String(i+1).padStart(2,'0')}</div>${badge('Do potwierdzenia','warning')}<h2>${r.title}</h2><p>${r.detail}</p></section>`).join('')}</div><section class="panel rule-summary"><h2>Ustalone w specyfikacji</h2><ul><li>Minimum 3 zawodników w kategorii.</li><li>Unikanie pierwszych walk pomiędzy zawodnikami tego samego klubu, gdy jest to możliwe.</li><li>Pierwszeństwo wolnego losu dla mistrzów Polski i Europy, gdy jest dostępny.</li><li>Układy i walki: drabinka. Techniki specjalne i testy siły: lista startowa.</li><li>Zmiana obecności dotyczy wszystkich startów zawodnika.</li><li>Na wydruku: pełna nazwa konkurencji, grupa wieku, płeć oraz stopień lub limit.</li></ul></section>`,'Zasady turnieju','Czytelne reguły. Widoczne miejsca wymagające decyzji.');}
function architecturePage(){return shell(`<section class="panel architecture-intro"><div class="eyebrow">MATDRAW · WIELE TURNIEJÓW</div><h2>Jeden zawodnik. Kolejne turnieje.</h2><p>Kartoteka należy do klubu. Zgłoszenie do turnieju jest osobnym rekordem z wiekiem, stopniem, konkurencjami i wagą na dane zawody. Kontrola i wyniki nie zmieniają innych turniejów.</p><div class="tech-flow"><span>Baza zawodników</span>${icon('arrow')}<span>Zgłoszenia do turniejów</span>${icon('arrow')}<span>Kontrola · drabinki · wyniki</span></div><a class="btn primary" href="./architecture.html" target="_blank" rel="noopener">Architektura i wdrożenie ${icon('external')}</a></section><div class="rules-grid"><section class="panel rule-card"><h2>Konta i role</h2><p>Logowanie e-mailem i hasłem. Administrator przydziela role i klub, Edytor prowadzi własne turnieje, Reprezentant zgłasza zawodników swojego klubu.</p></section><section class="panel rule-card"><h2>${isDemo?'Status podglądu Sites':'Połączenie z serwerem'}</h2><p>${isDemo?'W tym podglądzie konta i dane pozostają w tej przeglądarce. Do wspólnej pracy klubów potrzebne jest uruchomienie przygotowanego backendu PHP i bazy MySQL na Waszym hostingu.':'Aplikacja korzysta z backendu PHP i bazy MySQL. Uprawnienia są sprawdzane na serwerze przy każdej operacji.'}</p></section></div>`,'O projekcie','MatDraw · MEDUCASE · matdraw.mdcse.com');}
function render(){
 if(!workspace){renderLogin();return;}
 syncState();if(location.hash.startsWith('#screen')&&workspace.user.role!=='club'){renderScreen();return;}
 document.body.classList.remove('projection');
 if(ui.page==='accounts'&&workspace.user.role!=='admin')ui.page='tournaments';
 if(['overview','checkin','draws','screen'].includes(ui.page)&&workspace.user.role==='club')ui.page='athletes';
 if(['overview','athletes','checkin','draws'].includes(ui.page)&&!state.tournament.id)ui.page='tournaments';
 const pages={tournaments:tournamentsPage,database:databasePage,accounts:accountsPage,draws:drawsPage,overview:overviewPage,athletes:()=>rosterPage(false),checkin:()=>rosterPage(true),rules:rulesPage,architecture:architecturePage};
 document.querySelector('#app').innerHTML=(pages[ui.page]||tournamentsPage)();document.title='MatDraw — '+({tournaments:'Turnieje',database:'Baza zawodników',accounts:'Konta i role',draws:'Drabinki',athletes:'Zgłoszenia',checkin:'Kontrola startowa',overview:'Przegląd',rules:'Zasady turnieju',architecture:'O projekcie'}[ui.page]||'Turnieje');
}
function navigate(page){ui.page=page;ui.menu=false;history.replaceState(null,'','#'+page);render();window.scrollTo({top:0});}
function modal(title,body,actions='',large=false){
 previousFocus=document.activeElement;
 document.querySelector('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${large?'wide':''}" role="dialog" aria-modal="true" data-revision="${workspace?.revision||0}" aria-labelledby="modal-title" tabindex="-1"><header><h2 id="modal-title">${title}</h2><button class="icon-btn" data-action="close-modal" aria-label="Zamknij okno">${icon('close')}</button></header><div class="modal-body">${body}</div>${actions?'<footer class="modal-actions">'+actions+'</footer>':''}</section></div>`;
 document.body.classList.add('modal-open');const form=document.querySelector('.modal form');if(form&&workspace)form.dataset.revision=workspace.revision;document.querySelector('.modal input,.modal select,.modal button')?.focus();
}
function closeModal(){document.querySelector('#modal-root').innerHTML='';document.body.classList.remove('modal-open');if(previousFocus?.isConnected)previousFocus.focus();}
function showAttention(){const {items,unassigned}=allCats();modal('Zgłoszenia wymagające uwagi',`<p class="modal-lead">Te starty wymagają decyzji przed losowaniem.</p>${items.filter(c=>c.underfilled).map(c=>`<button class="attention-row" data-action="category" data-id="${esc(c.id)}"><span class="attention-count">${c.athletes.length}</span><div><strong>${esc(c.title)}</strong><small>${esc(c.subtitle)}</small></div>${icon('right')}</button>`).join('')}${unassigned.map(x=>`<div class="attention-row"><span class="attention-count">!</span><div><strong>${esc(x.athlete.name)} · ${EVENTS[x.event]}</strong><small>${esc(x.reason)}</small></div></div>`).join('')}`,button('Zasady turnieju','rules')+button('Rozumiem','close-modal','primary'));}
function matchModal(id){
 const c=selected(),d=ensureDraw(c),m=resolveDraw(d).flat().find(m=>m.id===id);if(!m)return;
 modal('Walka '+String(m.number).padStart(2,'0'),`<p class="modal-lead">${esc(c.title)} · ${esc(c.subtitle)}</p><p class="field-label">Wskaż zwycięzcę</p><div class="winner-options">${[m.a,m.b].map((id,i)=>{const a=athlete(id);return `<button class="winner-option ${i?'red':'blue'} ${m.winner===id?'selected':''}" data-action="choose-winner" data-match="${m.id}" data-id="${id}"><span class="avatar">${initials(a.name)}</span><span><strong>${esc(a.name)}</strong><small>${esc(a.club)}</small></span>${m.winner===id?icon('check'):icon('right')}</button>`;}).join('')}</div><p class="muted small">Zwycięzca automatycznie przechodzi do kolejnej rundy. ${isDemo?'Zapis dotyczy danych demonstracyjnych.':'Wynik jest zapisany dla tego turnieju.'}</p><div class="form-error" role="alert"></div>`,(m.recorded?button('Wycofaj wynik','clear-winner','danger-text',`data-match="${id}"`):'')+button('Anuluj','close-modal'));
}
function checkModal(id){const a=athlete(id);modal('Kontrola startowa',`<div class="check-athlete"><span class="avatar large">${initials(a.name)}</span><div><h3>${esc(a.name)}</h3><p>${esc(a.club)} · ${a.grade} ${a.gradeType==='dan'?'Dan':'Cup'}</p></div></div><form id="check-form" data-id="${id}"><div class="form-grid"><label>Status obecności<select name="presence"><option value="present" ${a.presence!=='absent'?'selected':''}>Obecny</option><option value="absent" ${a.presence==='absent'?'selected':''}>Nieobecny</option></select></label><label>Waga kontrolna (kg)<input name="actualWeight" type="number" min="10" max="250" step="0.1" value="${a.actualWeight??a.weight}"></label></div><div class="weight-summary"><span>Waga zgłoszona <strong>${a.weight.toFixed(1)} kg</strong></span><span>Tolerancja <strong>200 g*</strong></span></div><div id="check-impact" class="impact-box"></div><p class="muted small">* Robocza interpretacja: tolerancja przy górnej granicy zgłoszonej kategorii. Do zatwierdzenia przez trenera.</p><div class="form-error" role="alert"></div></form>`,button('Anuluj','close-modal')+'<button class="btn primary" form="check-form" type="submit">Zapisz kontrolę</button>');updateImpact();}
function checkCandidate(form){const a=athlete(form.dataset.id),f=new FormData(form);const value=String(f.get('actualWeight')).trim();const w=value===''?NaN:Number(value);return {...a,presence:f.get('presence'),actualWeight:f.get('presence')==='absent'?a.actualWeight:w};}
function updateImpact(){const form=document.querySelector('#check-form');if(!form)return;const before=athlete(form.dataset.id),after=checkCandidate(form);const box=document.querySelector('#check-impact');if(after.presence==='absent'){box.innerHTML=`${icon('alert')}<div><strong>Usunięcie ze wszystkich startów</strong><p>${after.events.map(e=>EVENTS[e]).join(' · ')}. Zgłoszenie pozostanie w historii.</p></div>`;return;}if(!Number.isFinite(after.actualWeight)){box.innerHTML='<span>Podaj wagę kontrolną.</span>';return;}const changed=after.events.filter(e=>classify(before,e).id!==classify(after,e).id);box.innerHTML=icon(changed.length?'refresh':'check')+`<div><strong>${changed.length?'Kategoria zmieni się automatycznie':'Kategorie pozostają bez zmian'}</strong><p>${changed.length?changed.map(e=>EVENTS[e]+': '+(classify(before,e).band||'do decyzji')+' → '+(classify(after,e).band||'do decyzji')).join('<br>'):'Potwierdzisz obecność i wagę zawodnika.'}</p></div>`;}
function printModal(){const c=selected();modal('Drukuj drabinki i listy',`<form id="print-form"><fieldset><legend>Zakres wydruku</legend><label class="radio-card"><input type="radio" name="scope" value="selected" checked><span><strong>Bieżąca kategoria</strong><small>${esc(c?.title||'')} · ${esc(c?.subtitle||'')}</small></span></label><label class="radio-card"><input type="radio" name="scope" value="all"><span><strong>Wszystkie obsadzone kategorie</strong><small>${allCats().items.length} kategorii · jedna kategoria na stronie lub kilka arkuszy</small></span></label></fieldset><label class="field-label print-format">Format papieru<select name="format"><option value="A4">A4 — poziomo</option><option value="A3">A3 — poziomo</option></select></label><p class="muted small">Możesz wybrać „Zapisz jako PDF” w oknie drukowania. Kategorie z mniej niż 3 osobami otrzymają listę z oznaczeniem „Do decyzji”.</p></form>`,button('Anuluj','close-modal')+'<button type="submit" form="print-form" class="btn primary">'+icon('print')+' Otwórz podgląd</button>');}
function printBracket(draw,rounds=null,startRound=0){const rr=rounds||resolveDraw(draw);return `<div class="print-tree" style="--print-rounds:${rr.length}">${rr.map((matches,i)=>`<section class="print-round"><h3>${roundName(i+startRound,Math.log2(draw.size))}</h3><div>${matches.map(m=>`<div class="print-match-position">${matchHtml(m,{interactive:false,compact:true})}</div>`).join('')}</div></section>`).join('')}</div>`;}
function doPrint(scope,format){
 const cats=scope==='all'?allCats().items:[selected()].filter(Boolean);const sheets=[];
 for(const c of cats){
  const d=ensureDraw(c);
  const base=(body,suffix='')=>`<article class="print-sheet"><header><div><strong class="print-brand">MatDraw.</strong><span>${esc(state.tournament.name)} · ${esc(state.tournament.city)}</span></div><span>${c.code}${suffix?' · '+suffix:''}</span></header><h1>${esc(c.title)}</h1><p class="print-subtitle">${esc(c.subtitle)}${c.event!=='forms'&&c.gradeType!=='all'?' · '+(c.gradeType==='dan'?'Dan':'Cup'):''} · ${c.athletes.length} zawodników${d?' · wersja '+d.revision:''}</p>${c.underfilled?'<p class="print-warning">DO DECYZJI — mniej niż 3 zawodników. Brak losowania.</p>':''}${body}<footer><span>${isDemo?'DEMO · DANE PRZYKŁADOWE':'MATDRAW'} · ${new Date().toLocaleDateString('pl-PL',{timeZone:'Europe/Warsaw'})}</span><a href="https://mdcse.com">Wykonano przez <img src="./assets/meducase.png" alt="MEDUCASE"></a></footer></article>`;
  if(c.type==='list'||!d){const pages=Math.ceil(c.athletes.length/12);for(let p=0;p<pages;p++){const part={...c,athletes:c.athletes.slice(p*12,(p+1)*12),printOffset:p*12};sheets.push(base(listView(part,true),pages>1?'Lista '+(p+1)+' / '+pages:''));}continue;}
  const rounds=resolveDraw(d);
  if(d.size<=16){sheets.push(base(printBracket(d)));continue;}
  const segments=d.size/16;
  for(let s=0;s<segments;s++){
   const part=rounds.slice(0,4).map((r,i)=>r.slice(s*(8/2**i),(s+1)*(8/2**i)));
   sheets.push(base(printBracket(d,part),'Sekcja '+(s+1)+' / '+segments));
  }
  sheets.push(base(printBracket(d,rounds.slice(4),4),'Finały sekcji'));
 }
 document.querySelector('#print-root').innerHTML=sheets.join('');
 document.querySelector('#print-root').dataset.format=format;
 document.querySelector('#print-root').style.setProperty('--sheet-height',format==='A3'?'272mm':'185mm');
 document.querySelector('#print-root').style.setProperty('--preview-width',format==='A3'?'420mm':'297mm');
 let style=document.querySelector('#print-page-size');if(!style){style=document.createElement('style');style.id='print-page-size';document.head.append(style);}style.textContent=`@page {size:${format==='A3'?'A3':'A4'} landscape;margin:10mm;}`;
 closeModal();
 document.body.classList.add('print-preview');
 let toolbar=document.querySelector('#print-toolbar');if(!toolbar){toolbar=document.createElement('div');toolbar.id='print-toolbar';document.body.append(toolbar);}
 toolbar.innerHTML=button(icon('left')+' Wróć do turnieju','exit-print')+`<span>Podgląd wydruku · ${format} poziomo · ${sheets.length} ${plural(sheets.length,'arkusz','arkusze','arkuszy')}</span>`+button(icon('print')+' Drukuj / zapisz PDF','native-print','primary');
 window.scrollTo({top:0});
}
function renderScreen(){
 document.body.classList.add('projection');
 const params=new URLSearchParams(location.hash.split('?')[1]||''),items=allCats().items;
 const c=items.find(x=>x.id===params.get('category'))||selected();
 if(!c){document.querySelector('#app').innerHTML='<main class="screen-empty">Brak kategorii do wyświetlenia. <a href="#draws">Wróć</a></main>';return;}
 ui.category=c.id;const d=ensureDraw(c);
 let parts=1,roundSet=null,startRound=0,partLabel='Cała drabinka';
 if(d&&d.size>8){
  const all=resolveDraw(d);parts=d.size/8;
  ui.screenPart=Math.min(ui.screenPart,parts);
  if(ui.screenPart===parts){roundSet=all.slice(3);startRound=3;partLabel='Finały sekcji';}
  else{roundSet=all.slice(0,3).map((r,i)=>r.slice(ui.screenPart*(4/2**i),(ui.screenPart+1)*(4/2**i)));partLabel='Sekcja '+String.fromCharCode(65+ui.screenPart)+' / '+String.fromCharCode(64+parts);}
 }
 document.querySelector('#app').innerHTML=`<main class="arena"><header class="arena-header"><a class="brand" href="#draws">${logo}</a><div class="arena-event"><strong>${esc(state.tournament.name)}</strong><span>TAEKWONDO · ${esc(state.tournament.city).toUpperCase()}</span></div><div class="arena-clock"><span class="pulse-dot"></span>${esc(state.tournament.mat)} <strong id="arena-time">${new Date().toLocaleTimeString('pl-PL',{hour:'2-digit',minute:'2-digit',timeZone:'Europe/Warsaw'})}</strong></div></header><div class="arena-controls"><select data-control="screen-category" aria-label="Kategoria na ekranie">${items.map(x=>`<option value="${esc(x.id)}" ${x.id===c.id?'selected':''}>${x.code} · ${esc(x.title)} · ${esc(x.subtitle)}</option>`).join('')}</select>${d&&d.size>8?`<select data-control="screen-part" aria-label="Sekcja drabinki">${Array.from({length:parts},(_,i)=>`<option value="${i}" ${ui.screenPart===i?'selected':''}>Sekcja ${String.fromCharCode(65+i)}</option>`).join('')}<option value="${parts}" ${ui.screenPart===parts?'selected':''}>Finały sekcji</option></select>${button(icon('refresh')+(ui.screenAuto?' Zatrzymaj zmianę':' Zmieniaj co 15 s'),'screen-auto')}`:''}${button(icon('expand')+' Pełny ekran','fullscreen')}${button(icon('left')+' Panel','exit-screen')}</div><div class="arena-title"><span class="category-code">${c.code}</span><h1>${esc(c.title)}</h1><p>${esc(c.subtitle)}${d&&d.size>8?' <span class="arena-part">'+partLabel+'</span>':''}</p></div>${c.underfilled?'<div class="arena-message">Kategoria oczekuje na decyzję organizatora.<br><small>Minimum 3 zawodników.</small></div>':c.type==='list'?listView(c):d?bracketHtml(d,false,{screen:true,roundSet:roundSet||resolveDraw(d),totalRounds:Math.log2(d.size),startRound}):'<div class="arena-message">Oczekiwanie na losowanie organizatora.</div>'}<div class="arena-caption"><span>${isDemo?'DEMO · Synchronizacja kart tej przeglądarki':'Dane z serwera · odświeżanie co 15 s'}</span><span>${d?'WERSJA '+d.revision:'LISTA STARTOWA'}</span></div>${footer()}</main>`;
 document.title='MatDraw — Ekran hali';
}
function tournamentsPage(){
 const user=workspace.user,q=ui.tournamentSearch.toLocaleLowerCase('pl'),list=workspace.tournaments.filter(t=>(t.name+' '+t.city).toLocaleLowerCase('pl').includes(q));
 return shell(`<div class="workspace-summary"><div><strong>${workspace.tournaments.length}</strong><span>Turniejów</span></div><div><strong>${workspace.profiles.filter(p=>!p.archived).length}</strong><span>${user.role==='club'?'Zawodników klubu':'W bazie zawodników'}</span></div><div><strong>${workspace.tournaments.filter(t=>t.status==='open').length}</strong><span>Otwartych zapisów</span></div></div><div class="collection-toolbar"><div class="search-field">${icon('search')}<input id="tournament-search" type="search" aria-label="Szukaj turnieju" placeholder="Szukaj turnieju lub miasta…" value="${esc(ui.tournamentSearch)}"></div><span class="muted small">Jedna baza zawodników. Wiele turniejów.</span></div><div class="tournament-grid">${list.map(t=>`<article class="tournament-card ${activeId===t.id?'current-tournament':''}"><div class="tournament-card-top"><span class="tournament-symbol">${icon('trophy')}</span>${badge(STATUSES[t.status],t.status==='open'?'teal':t.status==='finished'?'neutral':'warning')}</div><h2>${esc(t.name)}</h2><p>${formatDate(t.date)} <span>·</span> ${esc(t.city)}</p><div class="tournament-card-meta"><span>${icon('users')} ${t.entries.length} ${user.role==='club'?'zgłoszeń klubu':'zgłoszeń'}</span><span>${icon('bracket')} ${user.role==='club'?'Twoje zgłoszenia':Object.keys(t.draws).length+' drabinek'}</span></div><div class="tournament-card-actions">${button('Otwórz turniej '+icon('arrow'),'open-tournament','primary',`data-id="${t.id}"`)}${managesTournament(user,t)?button(icon('settings'),'edit-tournament','secondary icon-only',`data-id="${t.id}" aria-label="Ustawienia: ${esc(t.name)}"`):''}</div></article>`).join('')||'<section class="panel empty-state"><h3>Tu pojawią się turnieje.</h3><p>'+ (user.role==='club'?'Administrator lub Edytor musi najpierw otworzyć zapisy.':'Utwórz pierwszy turniej, a potem dodaj zgłoszenia z bazy zawodników.')+'</p></section>'}</div>`,'Turnieje',user.role==='club'?'Wybierz turniej i zgłoś zawodników swojego klubu.':'Twórz kolejne zawody i zarządzaj zgłoszeniami w jednym miejscu.',['admin','editor'].includes(user.role)?button(icon('plus')+' Nowy turniej','new-tournament','primary'):'');
}
function tournamentForm(id){const t=workspace.tournaments.find(t=>t.id===id)||{name:'',city:'',date:'',status:'draft',mat:'Mata 1'};modal(id?'Ustawienia turnieju':'Nowy turniej',`<form id="tournament-form" data-id="${id||''}"><div class="form-grid"><label class="span-two">Nazwa turnieju<input name="name" required maxlength="100" value="${esc(t.name)}" placeholder="np. Puchar Wiosny 2027"></label><label>Data zawodów<input name="date" type="date" required value="${t.date}" ${t.entries?.length?'readonly':''}></label><label>Miasto<input name="city" required maxlength="100" value="${esc(t.city)}"></label><label>Status<select name="status">${Object.entries(STATUSES).map(([v,l])=>`<option value="${v}" ${t.status===v?'selected':''}>${l}</option>`).join('')}</select></label><label>Nazwa maty<input name="mat" maxlength="50" required value="${esc(t.mat)}"></label></div><p class="muted small form-note">„Zapisy otwarte” pozwalają klubom dodawać zawodników. Zakończony turniej zachowuje historię i wyniki. ${t.entries?.length?'Data jest zablokowana, ponieważ są już zgłoszenia.':''}</p><div class="form-error" role="alert"></div></form>`,button('Anuluj','close-modal')+'<button class="btn primary" form="tournament-form" type="submit">'+(id?'Zapisz zmiany':'Utwórz turniej')+'</button>');}
function databasePage(){const q=ui.databaseSearch.toLocaleLowerCase('pl'),list=workspace.profiles.filter(a=>(ui.showArchive||!a.archived)&&(a.name+' '+clubName(a.clubId)).toLocaleLowerCase('pl').includes(q));return shell(`<div class="notice info-notice">${icon('info')}<p><strong>Kartoteka zostaje na kolejne zawody.</strong> Zmiana danych w bazie nie nadpisuje wcześniejszych zgłoszeń i wyników.</p></div><section class="panel roster-panel"><div class="roster-toolbar"><div class="search-field">${icon('search')}<input id="database-search" aria-label="Szukaj w bazie zawodników" type="search" placeholder="Szukaj zawodnika lub klubu…" value="${esc(ui.databaseSearch)}"></div><label class="checkbox-label"><input type="checkbox" data-control="archive" ${ui.showArchive?'checked':''}> Pokaż archiwum</label><span class="muted small">${list.length} osób</span></div><div class="table-wrap"><table class="roster-table"><thead><tr><th>Zawodnik</th><th>Klub</th><th>Data urodzenia / stopień</th><th>Turnieje</th><th><span class="sr-only">Działania</span></th></tr></thead><tbody>${list.map(a=>`<tr class="${a.archived?'absent':''}"><td data-label="Zawodnik"><div class="athlete-cell"><span class="avatar">${initials(a.name)}</span><span><strong>${esc(a.name)}</strong><small>${a.archived?'Archiwum':a.sex==='M'?'Mężczyzna / chłopiec':'Kobieta / dziewczynka'}</small></span></div></td><td data-label="Klub">${esc(clubName(a.clubId))}</td><td data-label="Urodzenie / stopień">${a.birthDate?formatDate(a.birthDate):'<span class="warning-text">Uzupełnij datę</span>'}<span class="separator">·</span>${a.grade} ${a.gradeType==='dan'?'Dan':'Cup'}</td><td data-label="Turnieje">${workspace.tournaments.filter(t=>t.entries.some(e=>e.profileId===a.id)).length}</td><td class="row-action"><div class="row-buttons">${!a.archived?button('Zgłoś','register-profile','small-btn',`data-id="${a.id}"`):''}${managesProfile(workspace.user,a)?button('Edytuj','edit-profile','small-btn',`data-id="${a.id}"`):''}</div></td></tr>`).join('')||'<tr><td colspan="5" class="empty-state">Brak zawodników. Dodaj pierwszą osobę do bazy.</td></tr>'}</tbody></table></div></section>`,'Baza zawodników',workspace.user.role==='club'?'Kartoteka Twojego klubu. Wybieraj te same osoby do kolejnych turniejów.':'Wspólna kartoteka, oddzielna od zgłoszeń turniejowych.',button(icon('plus')+' Nowy zawodnik','new-profile','primary'));}
function profileForm(id,register=false){const a=workspace.profiles.find(a=>a.id===id)||{name:'',clubId:workspace.user.clubId,sex:'M',birthDate:'',gradeType:'cup',grade:6,weight:60,height:170,events:['forms'],champion:false};modal(id?'Kartoteka zawodnika':register?'Nowy zawodnik i zgłoszenie':'Nowy zawodnik w bazie',`<form id="profile-form" data-id="${id||''}" data-register="${register?'yes':''}"><div class="form-grid"><label class="span-two">Imię i nazwisko<input name="name" value="${esc(a.name)}" required maxlength="100" autocomplete="off"></label><label class="span-two">Klub<select name="clubId" ${workspace.user.role==='club'?'disabled':''}>${workspace.clubs.map(c=>`<option value="${c.id}" ${a.clubId===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><label>Data urodzenia<input type="date" name="birthDate" ${a.legacyAge?'':'required'} value="${a.birthDate||''}" max="${new Date().toISOString().slice(0,10)}"></label><label>Płeć<select name="sex"><option value="M" ${a.sex==='M'?'selected':''}>Mężczyzna / chłopiec</option><option value="F" ${a.sex==='F'?'selected':''}>Kobieta / dziewczynka</option></select></label>${measureFields(a)}<fieldset class="span-two"><legend>Domyślne konkurencje${register?' na ten turniej':''}</legend>${eventFields(a.events)}</fieldset><label class="checkbox-label span-two"><input type="checkbox" name="champion" ${a.champion?'checked':''}> Mistrz Polski lub Europy</label></div><p class="muted small form-note">${register?'Po zapisie dodamy osobę do bazy i zgłosimy ją do: '+esc(state.tournament.name)+'.':'Dane służą do kolejnych zgłoszeń. Dotychczasowe turnieje zachowują swoje kopie.'} Wiek wyliczamy na dzień zawodów; zasada wymaga zatwierdzenia przez trenera.</p><div class="form-error" role="alert"></div></form>`,(id?button(a.archived?'Przywróć z archiwum':'Archiwizuj kartotekę','archive-profile','danger-text',`data-id="${id}" data-archived="${a.archived?'false':'true'}"`):'')+button('Anuluj','close-modal')+'<button class="btn primary" type="submit" form="profile-form">'+(register?'Zapisz i zgłoś':'Zapisz zawodnika')+'</button>',true);}
function measureFields(a){return `<label>Waga zgłoszona (kg)<input name="weight" type="number" min="10" max="250" step="0.1" value="${a.weight}" required></label><label>Wzrost (cm)<input name="height" type="number" min="70" max="250" step="1" value="${a.height}" required></label><label>Rodzaj stopnia<select name="gradeType"><option value="cup" ${a.gradeType==='cup'?'selected':''}>Cup</option><option value="dan" ${a.gradeType==='dan'?'selected':''}>Dan</option></select></label><label>Stopień<input name="grade" type="number" min="1" max="10" value="${a.grade}" required></label>`;}
function eventFields(events){return `<div class="event-checkboxes">${Object.entries(EVENTS).map(([k,v])=>`<label class="checkbox-label"><input type="checkbox" name="events" value="${k}" ${events?.includes(k)?'checked':''}>${v}</label>`).join('')}</div>`;}
function pickerModal(){const t=state.tournament;const list=workspace.profiles.filter(a=>!a.archived&&!t.entries.some(e=>e.profileId===a.id));modal('Dodaj zawodnika z bazy',`<p class="modal-lead">${esc(t.name)} · ${list.length} dostępnych osób</p><input class="picker-search" id="picker-search" type="search" placeholder="Szukaj zawodnika…" aria-label="Szukaj zawodnika w bazie"><div class="profile-picker">${list.map(a=>`<button class="picker-row" data-action="register-profile" data-id="${a.id}" data-search="${esc((a.name+' '+clubName(a.clubId)).toLocaleLowerCase('pl'))}"><span class="avatar">${initials(a.name)}</span><span><strong>${esc(a.name)}</strong><small>${esc(clubName(a.clubId))}</small></span>${icon('plus')}</button>`).join('')||'<p class="empty-state">Wszystkie dostępne osoby są już zgłoszone albo baza jest pusta.</p>'}</div><p class="picker-empty" hidden>Brak pasujących osób.</p>`,button(icon('plus')+' Utwórz nowego zawodnika','new-entry')+button('Zamknij','close-modal'));}
function entryForm(profileId,update=false){const profile=workspace.profiles.find(p=>p.id===profileId);if(!profile)throw Error('Nie znaleziono zawodnika.');const t=state.tournament;if(!t.id||!canEnter(workspace.user,t))throw Error('Wybierz turniej z otwartymi zapisami.');const current=update?t.entries.find(a=>a.profileId===profileId):null,a=current||profile;const age=profile.birthDate?ageAt(profile.birthDate,t.date):current?.age??'';modal(update?'Edytuj zgłoszenie':'Zgłoś zawodnika',`<div class="check-athlete"><span class="avatar large">${initials(profile.name)}</span><div><h3>${esc(profile.name)}</h3><p>${esc(clubName(profile.clubId))}</p></div></div><p class="entry-event-name">${icon('trophy')} ${esc(t.name)} · ${formatDate(t.date)}</p><form id="entry-form" data-id="${profileId}" data-update="${update?'yes':''}"><div class="form-grid"><label class="span-two">Wiek w dniu zawodów<input name="age" type="number" min="7" max="100" value="${age}" required ${profile.birthDate?'readonly':''}><small>${profile.birthDate?'Wyliczony z daty urodzenia.':'Starsza kartoteka nie ma daty urodzenia. Potwierdź wiek dla tego turnieju.'}</small></label>${measureFields(a)}<fieldset class="span-two"><legend>Konkurencje w tym turnieju</legend>${eventFields(a.events)}</fieldset><label class="checkbox-label span-two"><input type="checkbox" name="champion" ${a.champion?'checked':''}> Mistrz Polski lub Europy</label></div><p class="muted small form-note">Waga, stopień, konkurencje i późniejsza kontrola dotyczą wyłącznie tego turnieju.</p><div class="form-error" role="alert"></div></form>`,button('Anuluj','close-modal')+'<button type="submit" class="btn primary" form="entry-form">'+(update?'Zapisz zgłoszenie':'Zgłoś do turnieju')+'</button>',true);}
function canEditEntry(a){const u=workspace.user,t=state.tournament,p=workspace.profiles.find(x=>x.id===a.profileId);return canEnter(u,t)&&(managesTournament(u,t)||u.role==='club'&&a.clubId===u.clubId||u.role==='editor'&&p?.createdBy===u.id);}
function accountsPage(){return shell(`<div class="notice info-notice">${icon('shield')}<p><strong>Role przydziela Administrator.</strong> Reprezentanci widzą tylko kartotekę i zgłoszenia swojego klubu. Konto można zablokować bez usuwania historii.</p></div><section class="panel roster-panel"><div class="table-wrap"><table class="roster-table"><thead><tr><th>E-mail</th><th>Klub</th><th>Rola</th><th>Status</th><th>Działania</th></tr></thead><tbody>${workspace.users.map(u=>`<tr><td data-label="E-mail"><strong>${esc(u.email)}</strong>${u.id===workspace.user.id?' <small>(Ty)</small>':''}</td><td data-label="Klub">${esc(clubName(u.clubId))}</td><td data-label="Rola">${esc(ROLES[u.role])}</td><td data-label="Status">${badge(u.active?'Aktywne':'Zablokowane',u.active?'success':'warning')}</td><td class="row-action">${button('Zarządzaj','edit-account','small-btn',`data-id="${u.id}"`)}</td></tr>`).join('')}</tbody></table></div></section><div class="role-grid"><article class="panel"><h3>Administrator</h3><p>Wszystkie turnieje, kartoteki, zgłoszenia, wyniki oraz konta i role.</p></article><article class="panel"><h3>Edytor</h3><p>Tworzy i prowadzi własne turnieje, dodaje zawodników i edytuje własne kartoteki. Nie zarządza kontami.</p></article><article class="panel"><h3>Reprezentant klubu</h3><p>Dodaje i aktualizuje zawodników swojego klubu. Zgłasza ich do istniejących turniejów z otwartymi zapisami.</p></article></div>`,'Konta i role','Prosty dostęp: klub, e-mail, hasło i zakres uprawnień.',button(icon('plus')+' Nowe konto','new-account','primary'));}
function accountForm(id){const u=workspace.users.find(u=>u.id===id)||{email:'',clubId:'',role:'club',active:true};modal(id?'Zarządzaj kontem':'Nowe konto',`<form id="account-form" data-id="${id||''}"><div class="form-grid"><label class="span-two">E-mail<input name="email" type="email" required maxlength="254" value="${esc(u.email)}" autocomplete="off"></label><label class="span-two">Klub<select name="clubId"><option value="">Nowy klub — wpisz nazwę poniżej</option>${workspace.clubs.map(c=>`<option value="${c.id}" ${u.clubId===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><label class="span-two">Nazwa nowego klubu<input name="clubName" maxlength="100" placeholder="Wypełnij tylko dla nowego klubu"></label><label>Rola<select name="role">${Object.entries(ROLES).map(([r,l])=>`<option value="${r}" ${u.role===r?'selected':''}>${l}</option>`).join('')}</select></label><label>Status<select name="active"><option value="yes" ${u.active?'selected':''}>Aktywne</option><option value="no" ${!u.active?'selected':''}>Zablokowane</option></select></label><label class="span-two">${id?'Nowe hasło (opcjonalnie)':'Hasło'}<input name="password" type="password" autocomplete="new-password" minlength="12" maxlength="72" ${id?'':'required'}><small>Minimum 12 znaków. ${id?'Zmiana hasła kończy poprzednie sesje konta.':''}</small></label></div><div class="form-error" role="alert"></div>${isDemo?'<p class="muted small form-note">To konto testowe, dostępne wyłącznie w tej przeglądarce. Użyj hasła przeznaczonego do demonstracji.</p>':''}</form>`,button('Anuluj','close-modal')+'<button class="btn primary" type="submit" form="account-form">'+(id?'Zapisz zmiany':'Utwórz konto')+'</button>');}
function myAccount(){const u=workspace.user;modal('Moje konto',`<div class="account-summary"><strong>${esc(u.email)}</strong><p>${esc(clubName(u.clubId))} · ${ROLES[u.role]}</p></div><form id="password-form"><label class="field-label">Obecne hasło<input name="currentPassword" type="password" required autocomplete="current-password"></label><label class="field-label form-note">Nowe hasło<input name="password" type="password" required minlength="12" maxlength="72" autocomplete="new-password"></label><p class="muted small form-note">Minimum 12 znaków. Pozostałe sesje zostaną wylogowane.</p><div class="form-error" role="alert"></div></form>`,button('Zamknij','close-modal')+'<button class="btn primary" type="submit" form="password-form">Zmień hasło</button>');}
function renderLogin(message=''){
 document.body.classList.remove('projection','print-preview','modal-open');document.querySelector('#modal-root').innerHTML='';
 document.querySelector('#app').innerHTML=`<main class="login-page"><section class="login-story"><a class="brand" href="#tournaments">${logo}</a><div><span class="login-eyebrow">TWÓJ TURNIEJ. TWÓJ ZESPÓŁ.</span><h1>Od zgłoszenia<br>do finału.</h1><p>Wspólna baza zawodników, kolejne turnieje i czytelne drabinki. Wszystko w jednym miejscu.</p><div class="login-feature">${icon('users')} Konta klubów i proste zgłoszenia</div><div class="login-feature">${icon('trophy')} Wiele turniejów, osobna historia</div><div class="login-feature">${icon('screen')} Wydruk i ekran hali</div></div><span class="login-signature">MATDRAW · BY MEDUCASE</span></section><section class="login-form-panel"><div class="login-form-content"><span class="eyebrow">WITAJ W MATDRAW</span><h2>Zaloguj się</h2><p>Użyj konta otrzymanego od Administratora.</p>${isDemo?'<div class="login-demo-note">Podgląd demonstracyjny · konta i dane tylko w tej przeglądarce.</div>':''}<form id="login-form"><label class="field-label">E-mail<input name="email" type="email" autocomplete="username" required placeholder="twoj@klub.pl"></label><label class="field-label">Hasło<input name="password" type="password" autocomplete="current-password" required></label><div class="form-error" role="alert">${esc(message)}</div><button class="btn primary login-submit" type="submit">Zaloguj się ${icon('arrow')}</button></form>${isDemo?`<div class="demo-accounts"><span>Sprawdź przykładową rolę</span>${Object.entries(ROLES).map(([r,l])=>`<button class="demo-account" data-action="demo-login" data-role="${r}">${icon(r==='admin'?'shield':r==='editor'?'clipboard':'users')}<span>${l}</span>${icon('right')}</button>`).join('')}<p>Hasło kont demo: <code>MatDrawDemo2026!</code></p></div>`:'<p class="login-help">Nie masz konta lub nie pamiętasz hasła? Skontaktuj się z Administratorem turnieju.</p>'}</div>${footer()}</section></main>`;document.title='MatDraw — Logowanie';
}
function syncState(){
 if(!workspace)return;
 const fromScreen=location.hash.startsWith('#screen')?new URLSearchParams(location.hash.split('?')[1]||'').get('tournament'):null;
 if(fromScreen)activeId=fromScreen;
 if(!workspace.tournaments.some(t=>t.id===activeId))activeId=workspace.tournaments[0]?.id||null;
 const t=workspace.tournaments.find(t=>t.id===activeId)||{name:'',city:'',date:'',entries:[],draws:{},activity:[]};
 state={tournament:t,athletes:t.entries,draws:t.draws,activity:t.activity};
}
function switchTournament(id){activeId=id;sessionStorage.setItem('matdraw.activeTournament',id);ui.category=null;ui.search='';ui.event='all';ui.filter='all';ui.round=0;ui.screenPart=0;ui.rosterSearch='';closeModal();navigate(workspace.user.role==='club'?'athletes':'overview');}
const clubName=id=>workspace?.clubs.find(c=>c.id===id)?.name||'Klub';
const formatDate=date=>date?new Date(date+'T12:00:00').toLocaleDateString('pl-PL',{day:'numeric',month:'long',year:'numeric'}):'Brak daty';
async function commit(type,payload,expected=Number(document.querySelector('.modal')?.dataset.revision||workspace.revision)){
 if(saving)throw Error('Trwa zapisywanie. Poczekaj na potwierdzenie.');
 saving=true;
 try{const res=await Client.command(type,payload,expected);workspace=res.workspace;syncState();return res.result;}
 finally{saving=false;}
}
async function handleError(error,form){
 if(error.status===401){workspace=null;closeModal();renderLogin(error.message);return;}
 if(error.status===409){try{workspace=await Client.bootstrap();syncState();render();if(form)form.dataset.revision=workspace.revision;const dialog=document.querySelector('.modal');if(dialog)dialog.dataset.revision=workspace.revision;}catch{}}
 const box=form?.querySelector('.form-error')||document.querySelector('.form-error');if(box)box.textContent=error.message;else toast(error.message);
}
function entryPayload(f){return {age:Number(f.get('age')),weight:Number(f.get('weight')),height:Number(f.get('height')),gradeType:f.get('gradeType'),grade:Number(f.get('grade')),events:f.getAll('events'),champion:f.has('champion')};}
function project(){const c=selected();window.open(location.pathname+'#screen?tournament='+encodeURIComponent(activeId)+'&category='+encodeURIComponent(c?.id||''),'matdraw-screen-'+activeId);}
document.addEventListener('click',async event=>{
 const page=event.target.closest('[data-page]');if(page){event.preventDefault();closeModal();navigate(page.dataset.page);return;}
 const f=event.target.closest('[data-filter]');if(f){ui.filter=f.dataset.filter;render();return;}
 const el=event.target.closest('[data-action]');if(!el)return;
 const action=el.dataset.action,id=el.dataset.id;
 try{
  if(action==='demo-login'){el.disabled=true;const email={admin:'admin',editor:'editor',club:'club'}[el.dataset.role]+'@matdraw.example';workspace=await Client.login(email,'MatDrawDemo2026!');navigate('tournaments');return;}
  if(!workspace)return;
  if(action==='menu'){ui.menu=!ui.menu;render();}
  else if(action==='logout'){await Client.logout();workspace=null;closeModal();renderLogin();}
  else if(action==='refresh'){workspace=await Client.bootstrap();render();toast('Dane odświeżone.');}
  else if(action==='new-tournament')tournamentForm();
  else if(action==='edit-tournament')tournamentForm(id);
  else if(action==='open-tournament')switchTournament(id);
  else if(action==='new-profile')profileForm();
  else if(action==='edit-profile')profileForm(id);
  else if(action==='archive-profile'){await commit('profile.archive',{id,archived:el.dataset.archived==='true'});closeModal();render();toast('Kartoteka zaktualizowana. Dotychczasowe zgłoszenia zachowane.');}
  else if(action==='new-entry'||action==='add'){if(!canEnter(workspace.user,state.tournament))throw Error('Zapisy są zamknięte.');profileForm(null,true);}
  else if(action==='entry-picker')pickerModal();
  else if(action==='register-profile')entryForm(id);
  else if(action==='edit-entry')entryForm(id,true);
  else if(action==='remove-entry')modal('Wycofać zgłoszenie?',`<p>Wycofasz <strong>${esc(athlete(id)?.name)}</strong> z turnieju <strong>${esc(state.tournament.name)}</strong>. Kartoteka i inne turnieje pozostaną dostępne.</p>`,button('Anuluj','close-modal')+button('Wycofaj zgłoszenie','confirm-remove-entry','primary',`data-id="${id}"`));
  else if(action==='confirm-remove-entry'){await commit('entry.remove',{tournamentId:activeId,id});closeModal();render();toast('Zgłoszenie wycofane.');}
  else if(action==='new-account')accountForm();
  else if(action==='edit-account')accountForm(id);
  else if(action==='my-account')myAccount();
  else if(action==='category'){ui.category=id;ui.round=0;closeModal();navigate('draws');}
  else if(action==='attention')showAttention();
  else if(action==='close-modal')closeModal();
  else if(action==='rules'){closeModal();navigate('rules');}
  else if(action==='roster')navigate('athletes');
  else if(action==='project')project();
  else if(action==='print')printModal();
  else if(action==='native-print')window.print();
  else if(action==='exit-print'){document.body.classList.remove('print-preview');window.scrollTo({top:0});}
  else if(action==='check-athlete')checkModal(id);
  else if(action==='match')matchModal(el.dataset.match);
  else if(action==='choose-winner'){await commit('result.save',{tournamentId:activeId,categoryId:ui.category,matchId:el.dataset.match,winnerId:id});closeModal();render();toast('Wynik zapisany. Zwycięzca przechodzi do kolejnej rundy.');}
  else if(action==='clear-winner'){await commit('result.clear',{tournamentId:activeId,categoryId:ui.category,matchId:el.dataset.match});closeModal();render();toast('Wynik wycofany.');}
  else if(action==='create-draw'){await commit('draw.create',{tournamentId:activeId,categoryId:ui.category});render();toast('Losowanie zapisane.');}
  else if(action==='redraw'){const c=selected();modal('Wylosować drabinkę ponownie?',`<p>Zmieni się rozstawienie w kategorii <strong>${esc(c.title)} · ${esc(c.subtitle)}</strong>.</p><p>Wyniki innych kategorii i turniejów pozostaną zachowane.</p>`,button('Anuluj','close-modal')+button('Losuj ponownie','confirm-redraw','primary'));}
  else if(action==='confirm-redraw'){await commit('draw.create',{tournamentId:activeId,categoryId:ui.category});closeModal();render();toast('Nowe rozstawienie zapisane.');}
  else if(action==='screen-auto'){ui.screenAuto=!ui.screenAuto;renderScreen();}
  else if(action==='fullscreen'){if(!document.fullscreenElement)document.documentElement.requestFullscreen().catch(()=>toast('Pełny ekran nie jest dostępny.'));else document.exitFullscreen();}
  else if(action==='exit-screen'){if(document.fullscreenElement)document.exitFullscreen();navigate('draws');}
 }catch(error){el.disabled=false;await handleError(error);}
});
document.addEventListener('change',event=>{
 const el=event.target;if(el.closest('#check-form'))updateImpact();const control=el.dataset.control;
 if(control==='tournament'){switchTournament(el.value);}
 else if(control==='archive'){ui.showArchive=el.checked;render();}
 else if(control==='event'){ui.event=el.value;render();}
 else if(control==='category'){ui.category=el.value;ui.round=0;render();}
 else if(control==='round'){ui.round=Number(el.value);render();}
 else if(control==='roster-filter'){ui.rosterFilter=el.value;render();}
 else if(control==='screen-part'){ui.screenPart=Number(el.value);renderScreen();}
 else if(control==='screen-category'){ui.screenPart=0;location.hash='screen?tournament='+encodeURIComponent(activeId)+'&category='+encodeURIComponent(el.value);}
});
function filterRender(id){const input=document.querySelector('#'+id),start=input?.selectionStart;render();const next=document.querySelector('#'+id);if(next){next.focus();try{next.setSelectionRange(start,start);}catch{}}}
document.addEventListener('input',event=>{
 const el=event.target,fields={'category-search':'search','roster-search':'rosterSearch','database-search':'databaseSearch','tournament-search':'tournamentSearch'};
 if(fields[el.id]){ui[fields[el.id]]=el.value;filterRender(el.id);}
 if(el.id==='picker-search'){let visible=0;document.querySelectorAll('.picker-row').forEach(row=>{row.hidden=!row.dataset.search.includes(el.value.toLocaleLowerCase('pl'));if(!row.hidden)visible++;});document.querySelector('.picker-empty').hidden=visible>0;}
 if(el.closest('#check-form'))updateImpact();
});
document.addEventListener('submit',async event=>{
 const ids=['login-form','tournament-form','profile-form','entry-form','account-form','password-form','check-form','print-form'];
 if(!ids.includes(event.target.id))return;event.preventDefault();
 const form=event.target,f=new FormData(form),submit=event.submitter,revision=Number(form.dataset.revision||workspace?.revision);
 if(submit?.disabled)return;if(submit)submit.disabled=true;
 const errorBox=form.querySelector('.form-error');if(errorBox)errorBox.textContent='';
 try{
  if(form.id==='login-form'){workspace=await Client.login(f.get('email'),f.get('password'));navigate('tournaments');return;}
  if(form.id==='print-form'){doPrint(f.get('scope'),f.get('format'));return;}
  if(form.id==='tournament-form'){const result=await commit('tournament.save',{id:form.dataset.id||undefined,name:f.get('name'),city:f.get('city'),date:f.get('date'),status:f.get('status'),mat:f.get('mat')},revision);activeId=result.id;sessionStorage.setItem('matdraw.activeTournament',activeId);}
  else if(form.id==='profile-form'){
   const p={id:form.dataset.id||undefined,name:f.get('name'),clubId:f.get('clubId')||workspace.user.clubId,birthDate:f.get('birthDate'),sex:f.get('sex'),...entryPayload(f)};
   if(form.dataset.register==='yes')p.registration={tournamentId:activeId,...entryPayload(f)};
   await commit('profile.save',p,revision);
  }else if(form.id==='entry-form')await commit('entry.save',{tournamentId:activeId,profileId:form.dataset.id,update:form.dataset.update==='yes',...entryPayload(f)},revision);
  else if(form.id==='account-form')await commit('account.save',{id:form.dataset.id||undefined,email:f.get('email'),clubId:f.get('clubId'),clubName:f.get('clubName'),role:f.get('role'),active:f.get('active')==='yes',password:f.get('password')||undefined},revision);
  else if(form.id==='password-form')await commit('account.password',{id:workspace.user.id,currentPassword:f.get('currentPassword'),password:f.get('password')},revision);
  else if(form.id==='check-form')await commit('checkin.save',{tournamentId:activeId,id:form.dataset.id,presence:f.get('presence'),actualWeight:f.get('actualWeight')},revision);
  closeModal();render();toast('Zapisano zmiany.');
 }catch(error){await handleError(error,form);}finally{if(submit?.isConnected)submit.disabled=false;}
});
document.addEventListener('keydown',event=>{
 const modalEl=document.querySelector('.modal');if(!modalEl)return;
 if(event.key==='Escape'){event.preventDefault();closeModal();}
 if(event.key==='Tab'){const focusable=[...modalEl.querySelectorAll('button:not([disabled]),input:not([disabled]),select:not([disabled]),a[href]')],first=focusable[0],last=focusable.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}
});
window.addEventListener('storage',async e=>{if(!workspace||e.key!==Client.dataKey)return;try{workspace=await Client.bootstrap();if(!document.querySelector('.modal'))render();}catch(error){await handleError(error);}});
window.addEventListener('hashchange',()=>{if(!location.hash.startsWith('#screen'))ui.page=location.hash.slice(1)||'tournaments';render();});
setInterval(()=>{const el=document.querySelector('#arena-time');if(el)el.textContent=new Date().toLocaleTimeString('pl-PL',{hour:'2-digit',minute:'2-digit',timeZone:'Europe/Warsaw'});},30000);
setInterval(async()=>{if(workspace&&location.hash.startsWith('#screen')){try{workspace=await Client.bootstrap();syncState();if(ui.screenAuto){const d=ensureDraw(selected());if(d&&d.size>8)ui.screenPart=(ui.screenPart+1)%(d.size/8+1);}renderScreen();}catch(error){await handleError(error);}}},15000);
ui.page=location.hash.startsWith('#screen')?'draws':location.hash.slice(1)||'tournaments';
document.querySelector('#app').innerHTML='<div class="app-loading">Uruchamianie MatDraw…</div>';
try{workspace=await Client.init();render();}catch(error){renderLogin(error.message);}
